insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6d6d98fe-6994-45ef-8564-9717f5ad89c0', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Anthropological Research as Craft, Science, and Public Practice', 'This opening topic frames research methods as a disciplined way of producing accountable knowledge about human life. Students learn that anthropology combines interpretive, comparative, historical, and empirical habits of inquiry.', 0),
  ('061cdf1e-5573-4ba9-a8bf-e7297454815e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6d6d98fe-6994-45ef-8564-9717f5ad89c0', 'subtopic'::public.curated_course_node_type, 'Four-field and applied research logics', 'Students see how methods vary across cultural, linguistic, archaeological, biological, public, and applied anthropology.', 0),
  ('aa9f3ef9-8ad0-4e6c-95e2-68d66b32c60d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '061cdf1e-5573-4ba9-a8bf-e7297454815e', 'concept'::public.curated_course_node_type, 'Research traditions across anthropology subfields', null, 0),
  ('266d05e3-dc66-40e2-abcc-3be4afc16029', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '061cdf1e-5573-4ba9-a8bf-e7297454815e', 'concept'::public.curated_course_node_type, 'Humanistic interpretation and social-scientific evidence', null, 1),
  ('ff8cdb07-96b1-468c-9578-ff10622b1261', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '061cdf1e-5573-4ba9-a8bf-e7297454815e', 'concept'::public.curated_course_node_type, 'Academic, public, policy, and community audiences', null, 2),
  ('ad57ce78-ed84-4157-9d10-a3baf8d495fe', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6d6d98fe-6994-45ef-8564-9717f5ad89c0', 'subtopic'::public.curated_course_node_type, 'Evidence, interpretation, and uncertainty', 'The point is to treat anthropological claims as arguments built from situated evidence.', 1),
  ('91a24dca-47ab-4c25-8738-c35679747e3f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'ad57ce78-ed84-4157-9d10-a3baf8d495fe', 'concept'::public.curated_course_node_type, 'Observation, interview, archive, artifact, survey, and digital evidence', null, 0),
  ('957f27d4-10ef-40a3-827b-4c0629c45c5d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'ad57ce78-ed84-4157-9d10-a3baf8d495fe', 'concept'::public.curated_course_node_type, 'Triangulation and competing explanations', null, 1),
  ('61b87ee7-274e-4267-81aa-9a816664e65d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'ad57ce78-ed84-4157-9d10-a3baf8d495fe', 'concept'::public.curated_course_node_type, 'Limits, bias, and uncertainty in field-based knowledge', null, 2),
  ('837ec922-0cfc-486c-8512-aa0efc544e9e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6d6d98fe-6994-45ef-8564-9717f5ad89c0', 'subtopic'::public.curated_course_node_type, 'Methods as relationships', 'Students learn that anthropology is shaped by relationships with people, places, institutions, and histories.', 2),
  ('6b5b8cea-8e79-495a-b839-64b07363fb2d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '837ec922-0cfc-486c-8512-aa0efc544e9e', 'concept'::public.curated_course_node_type, 'Trust, rapport, access, and refusal', null, 0),
  ('f44985b2-8b62-4f1a-8b8a-65dfcdf0c04a', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '837ec922-0cfc-486c-8512-aa0efc544e9e', 'concept'::public.curated_course_node_type, 'Researcher responsibilities before and after fieldwork', null, 1),
  ('ac35fb8e-3fdf-421c-b3eb-e302f12933d1', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '837ec922-0cfc-486c-8512-aa0efc544e9e', 'concept'::public.curated_course_node_type, 'Reciprocity, accountability, and long-term consequences', null, 2),
  ('4d6ad2ef-f650-4e80-af49-d32e3dec2e4d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Research Questions, Literature Review, and Theory', 'A strong methods project begins before data collection. This topic teaches students to develop meaningful questions, read scholarly conversations, and connect theory to research design.', 1),
  ('6b069575-12d5-4cc2-88cd-ee7e04ef00dd', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '4d6ad2ef-f650-4e80-af49-d32e3dec2e4d', 'subtopic'::public.curated_course_node_type, 'Question design', 'Students learn to move from broad curiosity to researchable problems.', 0),
  ('7b87feef-9602-4789-bd84-bd1f5b368255', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6b069575-12d5-4cc2-88cd-ee7e04ef00dd', 'concept'::public.curated_course_node_type, 'Descriptive, interpretive, comparative, and explanatory questions', null, 0),
  ('f544beed-682b-4dd5-a567-1ddbad1cd43b', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6b069575-12d5-4cc2-88cd-ee7e04ef00dd', 'concept'::public.curated_course_node_type, 'Scope, feasibility, and ethical stakes', null, 1),
  ('c8d43706-12f8-4941-b2d7-fb57e0f27475', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6b069575-12d5-4cc2-88cd-ee7e04ef00dd', 'concept'::public.curated_course_node_type, 'Conceptual definitions and operational decisions', null, 2),
  ('e80a05d6-d243-4cc4-ad73-a8f1be8d2a33', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '4d6ad2ef-f650-4e80-af49-d32e3dec2e4d', 'subtopic'::public.curated_course_node_type, 'Literature review strategy', 'The gist is to find the conversation a project is entering.', 1),
  ('b6b9b350-1abe-4d15-b409-a1df61404968', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'e80a05d6-d243-4cc4-ad73-a8f1be8d2a33', 'concept'::public.curated_course_node_type, 'AnthroSource, library databases, bibliographies, and citation chaining', null, 0),
  ('1dadefe9-4b46-4dc0-91a0-0c521c8f830c', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'e80a05d6-d243-4cc4-ad73-a8f1be8d2a33', 'concept'::public.curated_course_node_type, 'Classic texts versus current debates', null, 1),
  ('a642b846-729d-4dc4-9f70-9156e22f2425', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'e80a05d6-d243-4cc4-ad73-a8f1be8d2a33', 'concept'::public.curated_course_node_type, 'Annotated bibliographies and synthesis matrices', null, 2),
  ('bd73595a-c721-46e9-b92a-b1c1135d5dfb', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '4d6ad2ef-f650-4e80-af49-d32e3dec2e4d', 'subtopic'::public.curated_course_node_type, 'Theory-method alignment', 'Students practice choosing methods that actually answer the theoretical question.', 2),
  ('f3e3de5b-c133-4410-84f0-9ada418c0567', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'bd73595a-c721-46e9-b92a-b1c1135d5dfb', 'concept'::public.curated_course_node_type, 'Practice theory, political economy, interpretive anthropology, feminism, postcolonial theory', null, 0),
  ('efa920b7-f744-4f7f-ad70-da480151a967', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'bd73595a-c721-46e9-b92a-b1c1135d5dfb', 'concept'::public.curated_course_node_type, 'Emic and etic framing', null, 1),
  ('c7ac46fe-374b-4af0-8f09-ecc9b7043c3e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'bd73595a-c721-46e9-b92a-b1c1135d5dfb', 'concept'::public.curated_course_node_type, 'Theory as lens, not decoration', null, 2),
  ('2f4a7000-6863-4af2-9766-070048cbde7e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Research Design, Sampling, and Fieldsite Selection', 'This topic turns an idea into a defensible study plan. Students learn how to select sites, participants, cases, and methods with purpose rather than convenience alone.', 2),
  ('167122b6-9d9b-4ac7-a091-c553b453521a', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2f4a7000-6863-4af2-9766-070048cbde7e', 'subtopic'::public.curated_course_node_type, 'Fieldsite selection', 'Students learn why sites are constructed through questions, access, relationships, and scale.', 0),
  ('3728a3df-a603-488e-bd29-2ade62025fb8', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '167122b6-9d9b-4ac7-a091-c553b453521a', 'concept'::public.curated_course_node_type, 'Single-site, multi-sited, virtual, archival, and institutional fieldsites', null, 0),
  ('d3db0297-d003-4f10-b1f0-ab11f7723c85', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '167122b6-9d9b-4ac7-a091-c553b453521a', 'concept'::public.curated_course_node_type, 'Gatekeepers, permissions, and access politics', null, 1),
  ('9e8c3516-7902-4e2a-adbe-faacab8f81a5', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '167122b6-9d9b-4ac7-a091-c553b453521a', 'concept'::public.curated_course_node_type, 'Feasibility, safety, language, and time constraints', null, 2),
  ('db667ae6-d1e5-4de1-ac7e-e90882eb1ee0', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2f4a7000-6863-4af2-9766-070048cbde7e', 'subtopic'::public.curated_course_node_type, 'Sampling in anthropology', 'The point is to distinguish statistical representativeness from theoretical and purposive sampling.', 1),
  ('de589348-7687-474f-9348-bd018027e78b', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'db667ae6-d1e5-4de1-ac7e-e90882eb1ee0', 'concept'::public.curated_course_node_type, 'Purposive, snowball, quota, convenience, and respondent-driven sampling', null, 0),
  ('5073f8e6-cd21-4c55-8340-fd69a3a66c98', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'db667ae6-d1e5-4de1-ac7e-e90882eb1ee0', 'concept'::public.curated_course_node_type, 'Key informants, cases, events, and documents', null, 1),
  ('a0cc97b5-bbcb-41e5-b369-46bfeaa4f5e3', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'db667ae6-d1e5-4de1-ac7e-e90882eb1ee0', 'concept'::public.curated_course_node_type, 'Sample size, saturation, and variation', null, 2),
  ('77fdae17-272a-41bb-a1e8-398bdaaf57c2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2f4a7000-6863-4af2-9766-070048cbde7e', 'subtopic'::public.curated_course_node_type, 'Mixed-method design', 'Students learn how qualitative and quantitative elements can reinforce each other.', 2),
  ('7d633d15-4ef8-4ed6-9ab1-91eb2b746587', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '77fdae17-272a-41bb-a1e8-398bdaaf57c2', 'concept'::public.curated_course_node_type, 'Sequential, convergent, and embedded designs', null, 0),
  ('e510dad9-28da-4fa4-b210-25dc67c95cf3', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '77fdae17-272a-41bb-a1e8-398bdaaf57c2', 'concept'::public.curated_course_node_type, 'When surveys complement ethnography', null, 1),
  ('a264b0b1-849b-4840-830b-9c7250dcdbbc', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '77fdae17-272a-41bb-a1e8-398bdaaf57c2', 'concept'::public.curated_course_node_type, 'Integration plans and points of triangulation', null, 2),
  ('fb1f74c7-7149-4a99-b447-105c4b600476', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Ethics, Consent, IRB, and Risk', 'Anthropological methods require ethical judgment, not checkbox compliance. This topic prepares students to protect participants, communities, data, and themselves.', 3);
