values
  ('53c40f9b-e08c-4128-94b9-a12fd744e4b6', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'fb1f74c7-7149-4a99-b447-105c4b600476', 'subtopic'::public.curated_course_node_type, 'Informed consent in context', 'Students learn that consent is a continuing relationship rather than a signed form alone.', 0),
  ('db3740d5-91c7-4f22-9160-b076311a7174', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '53c40f9b-e08c-4128-94b9-a12fd744e4b6', 'concept'::public.curated_course_node_type, 'Written, oral, implied, and process consent', null, 0),
