  ('9ea6b3d0-cebb-44cd-a775-edaf4336355b', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'a17eaaa9-5f7b-42cb-aa95-e8455a028da9', 'concept'::public.curated_course_node_type, 'Belmont principles and Common Rule basics', null, 0),
