  ('094213c8-a448-47ca-abbe-5367e9768c81', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'a17eaaa9-5f7b-42cb-aa95-e8455a028da9', 'concept'::public.curated_course_node_type, 'Protocol writing, amendments, adverse events, and confidentiality plans', null, 2),
