  ('4dfc114a-fbaf-48b0-b332-ee016323599d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2f226076-1c6b-45f0-a555-5aa80144b0cc', 'concept'::public.curated_course_node_type, 'Do no harm, transparency, and avoiding secret research', null, 0),
  ('5e66cd97-b680-4656-84a8-519fa82f6bd6', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2f226076-1c6b-45f0-a555-5aa80144b0cc', 'concept'::public.curated_course_node_type, 'Community review, Indigenous data sovereignty, and cultural protocols', null, 1),
  ('8e9eaa14-8b32-455e-9d9f-1441d64ae890', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2f226076-1c6b-45f0-a555-5aa80144b0cc', 'concept'::public.curated_course_node_type, 'Researcher safety, trauma, and fieldwork boundaries', null, 2),
  ('8d1448d5-a804-4395-bbb9-e6cdcdb10c2d', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Reflexivity, Positionality, and Power', 'This topic teaches students to examine how knowledge is shaped by who asks, who answers, and under what conditions. Reflexivity becomes a method for improving, not weakening, research.', 4),
