  ('0735b93f-148c-44b1-bfa6-c63d6a1f4eb1', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '394364e1-3577-4eca-92be-729d293b2342', 'concept'::public.curated_course_node_type, 'Positionality as analytic evidence', null, 2),
