  ('f07bdef4-82e1-4776-9381-07f9329752df', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6b5b16c6-b13f-475b-b698-f9d16e617100', 'concept'::public.curated_course_node_type, 'Reflexive journaling and analytic memos', null, 0),
