  ('14936726-91d9-4412-a034-85bc3cd2c69c', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '46e5adad-0da6-4c48-ac84-a5c89aa976cb', 'concept'::public.curated_course_node_type, 'Collaborative authority and co-analysis', null, 1),
