  ('2103cef0-d69c-4d01-902a-48106c9316f9', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Participant Observation', 'Participant observation is the signature ethnographic method. Students learn how to observe, participate, build rapport, and notice patterns without pretending to be invisible.', 5),
  ('76929e57-6829-42ed-9004-0d7717f5e455', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2103cef0-d69c-4d01-902a-48106c9316f9', 'subtopic'::public.curated_course_node_type, 'Observation strategies', 'Students practice turning ordinary scenes into systematic field data.', 0),
  ('ee73da8f-421d-45ba-8958-a94ca127d6ad', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '76929e57-6829-42ed-9004-0d7717f5e455', 'concept'::public.curated_course_node_type, 'Descriptive, focused, and selective observation', null, 0),
  ('60cdcda5-112e-4c32-90da-06448bb2c76e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '76929e57-6829-42ed-9004-0d7717f5e455', 'concept'::public.curated_course_node_type, 'Settings, actors, activities, objects, time, goals, and feelings', null, 1),
  ('47d91a37-c8a2-464b-ba64-54af68d7b919', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '76929e57-6829-42ed-9004-0d7717f5e455', 'concept'::public.curated_course_node_type, 'Mapping spaces, routines, and interaction patterns', null, 2),
  ('8f4b2a47-893f-4f32-891b-56d11c9b8910', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2103cef0-d69c-4d01-902a-48106c9316f9', 'subtopic'::public.curated_course_node_type, 'Participation and rapport', 'The gist is to understand immersion as negotiated involvement.', 1),
  ('23afb583-4efc-47ea-931c-b5db80583d59', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '8f4b2a47-893f-4f32-891b-56d11c9b8910', 'concept'::public.curated_course_node_type, 'Roles from observer to participant', null, 0),
  ('764c8a2c-249c-4a20-b1e9-594295f90a90', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '8f4b2a47-893f-4f32-891b-56d11c9b8910', 'concept'::public.curated_course_node_type, 'Trust-building and boundaries', null, 1),
  ('b1b74536-ed41-4f59-b17b-cad4775923b0', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '8f4b2a47-893f-4f32-891b-56d11c9b8910', 'concept'::public.curated_course_node_type, 'Managing disclosure, expectations, and conflict', null, 2),
  ('74c4ed33-9630-42bd-8a46-f9ffe11ed1d2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2103cef0-d69c-4d01-902a-48106c9316f9', 'subtopic'::public.curated_course_node_type, 'Analytic noticing', 'Students learn to move from seeing to interpreting.', 2),
  ('f9e60c2a-007a-44ab-820f-c7b0796afe1f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '74c4ed33-9630-42bd-8a46-f9ffe11ed1d2', 'concept'::public.curated_course_node_type, 'Rituals, routines, silences, contradictions, and exceptions', null, 0),
  ('c7ec13b8-d0bd-4066-aa2f-01c5048f5149', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '74c4ed33-9630-42bd-8a46-f9ffe11ed1d2', 'concept'::public.curated_course_node_type, 'Pattern recognition across events', null, 1),
  ('074f3757-7a20-4e07-8d0c-258cb52bc3b4', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '74c4ed33-9630-42bd-8a46-f9ffe11ed1d2', 'concept'::public.curated_course_node_type, 'Questions generated from observation', null, 2),
  ('af5a82e1-649f-4a65-bcd2-98c1eb636aa3', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Fieldnotes and Documentation', 'Fieldnotes are the working memory of ethnography. This topic teaches students to record, organize, protect, and analyze field experiences with rigor.', 6),
  ('4d9cbc4c-2b03-434f-bbe2-3960cab2b6d2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'af5a82e1-649f-4a65-bcd2-98c1eb636aa3', 'subtopic'::public.curated_course_node_type, 'Jottings and expanded notes', 'Students learn note-taking rhythms that preserve detail without disrupting the field.', 0);
