  ('a212318f-553c-496b-afb8-e2eded4e7171', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '20275c87-0660-4334-be50-e929c39611a7', 'concept'::public.curated_course_node_type, 'Consent for recording and images', null, 0),
  ('4cf80edf-fb59-41c0-a297-8fded0334a40', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '20275c87-0660-4334-be50-e929c39611a7', 'concept'::public.curated_course_node_type, 'Metadata, filenames, storage, and backups', null, 1),
  ('09683de2-c55f-4dbf-931d-38ff47351b11', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '20275c87-0660-4334-be50-e929c39611a7', 'concept'::public.curated_course_node_type, 'Captioning and contextual annotation', null, 2),
