  ('c28c2aa1-f116-4949-841a-4e6e79f8bcc8', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'd3b8732b-84ae-4281-8760-69e022c15eb4', 'concept'::public.curated_course_node_type, 'Structured, semi-structured, unstructured, life-history, and expert interviews', null, 0),
  ('dade2dee-6666-478b-8f61-3216b1618811', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'd3b8732b-84ae-4281-8760-69e022c15eb4', 'concept'::public.curated_course_node_type, 'Question wording, sequence, probes, and follow-ups', null, 1),
  ('fb6cb4ca-3bcf-4b62-b06c-116be7b3baab', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'd3b8732b-84ae-4281-8760-69e022c15eb4', 'concept'::public.curated_course_node_type, 'Pilot interviews and protocol revision', null, 2),
  ('9d94eb87-60dc-49cc-bfc2-2684c2cca2e9', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3511bbe4-3168-4b4f-9cf0-1c9ac4e04b94', 'subtopic'::public.curated_course_node_type, 'Interview practice', 'The gist is to develop listening as a research skill.', 1),
  ('47b67f36-3dae-4da8-8b97-08323fb0986a', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '9d94eb87-60dc-49cc-bfc2-2684c2cca2e9', 'concept'::public.curated_course_node_type, 'Rapport, pacing, silence, and active listening', null, 0),
  ('a51339b8-d81f-4b00-bab8-6bdb1b7894c6', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '9d94eb87-60dc-49cc-bfc2-2684c2cca2e9', 'concept'::public.curated_course_node_type, 'Recording, transcription, translation, and interpretation', null, 1),
