  ('7af3f25f-f9d2-46f7-8a22-080ab8c26c70', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3511bbe4-3168-4b4f-9cf0-1c9ac4e04b94', 'subtopic'::public.curated_course_node_type, 'Oral history and memory', 'Students learn how memory is evidence, interpretation, and performance.', 2),
  ('68b41c2e-706d-4b76-b3d2-f58ba649dc50', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7af3f25f-f9d2-46f7-8a22-080ab8c26c70', 'concept'::public.curated_course_node_type, 'Narrative structure and life-course context', null, 0),
  ('3de9cce9-b9bc-45f0-a259-5ecd18e1c2cc', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7af3f25f-f9d2-46f7-8a22-080ab8c26c70', 'concept'::public.curated_course_node_type, 'Collective memory and historical trauma', null, 1),
  ('293d9bd2-49a0-42c8-8a27-38ca39fc05f3', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7af3f25f-f9d2-46f7-8a22-080ab8c26c70', 'concept'::public.curated_course_node_type, 'Rights, archives, and participant review', null, 2),
