  ('59f6c72c-a9f7-4beb-8eb7-b08423bc8d27', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '28ffcbf6-e0e3-4f86-adaa-83ae245b47ff', 'concept'::public.curated_course_node_type, 'Recruitment, group composition, facilitation, and ground rules', null, 0),
  ('83e6dcc0-00cb-499b-b356-13f1db743fe0', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '28ffcbf6-e0e3-4f86-adaa-83ae245b47ff', 'concept'::public.curated_course_node_type, 'Consensus, disagreement, status, and silence', null, 1),
  ('9848a55b-9bcc-4e67-9b6e-ca50424f90c5', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '28ffcbf6-e0e3-4f86-adaa-83ae245b47ff', 'concept'::public.curated_course_node_type, 'Confidentiality limits in group settings', null, 2),
  ('d9f35d94-2e94-4ddd-b5ed-09806bfe1bc7', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7659d30a-8c29-4d53-9953-fbbb5921c728', 'subtopic'::public.curated_course_node_type, 'Elicitation techniques', 'The point is to use prompts that help participants explain meanings and categories.', 1),
  ('4f764166-0957-487c-9b9e-b0e4781e3873', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'd9f35d94-2e94-4ddd-b5ed-09806bfe1bc7', 'concept'::public.curated_course_node_type, 'Photo elicitation, object elicitation, free listing, pile sorting, and mapping', null, 0),
  ('2a109024-f67c-4a4c-9566-986c95d91059', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'd9f35d94-2e94-4ddd-b5ed-09806bfe1bc7', 'concept'::public.curated_course_node_type, 'Cognitive anthropology and domain analysis', null, 1),
  ('74cbfd3a-db30-489b-bbac-b085268e5934', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'd9f35d94-2e94-4ddd-b5ed-09806bfe1bc7', 'concept'::public.curated_course_node_type, 'When prompts reveal assumptions that direct questions miss', null, 2),
  ('06f342dc-626b-465a-86aa-1faba929bba5', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7659d30a-8c29-4d53-9953-fbbb5921c728', 'subtopic'::public.curated_course_node_type, 'Participatory methods', 'Students practice designing research with people rather than only about them.', 2),
  ('53009aab-1032-43e1-8b3b-e1e4ff15e822', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '06f342dc-626b-465a-86aa-1faba929bba5', 'concept'::public.curated_course_node_type, 'Participatory action research', null, 0),
  ('354850be-b59e-46f4-9f77-802ad28b349f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '06f342dc-626b-465a-86aa-1faba929bba5', 'concept'::public.curated_course_node_type, 'Community mapping, timelines, workshops, and feedback sessions', null, 1),
  ('2da0e915-4ae0-45a3-936f-e40bc5583689', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '06f342dc-626b-465a-86aa-1faba929bba5', 'concept'::public.curated_course_node_type, 'Shared ownership, compensation, and decision-making', null, 2),
  ('cf9d1f6b-c3c0-4c04-b6d9-2361d976df8c', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Surveys, Measurement, and Mixed Methods', 'Anthropologists often need structured data alongside ethnography. This topic teaches careful survey design, measurement, and integration without reducing culture to numbers alone.', 9),
  ('7cb83c4d-2e13-43fd-9357-ab1b69f3aef2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'cf9d1f6b-c3c0-4c04-b6d9-2361d976df8c', 'subtopic'::public.curated_course_node_type, 'Questionnaire design', 'Students learn to write survey items that produce interpretable data.', 0),
  ('418b42d7-35d1-4cff-b277-88a1ffabea86', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7cb83c4d-2e13-43fd-9357-ab1b69f3aef2', 'concept'::public.curated_course_node_type, 'Closed, open, Likert, ranking, and demographic items', null, 0);
