  ('fa322727-6aab-4e6e-b5cb-594e1a956ede', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'cf9d1f6b-c3c0-4c04-b6d9-2361d976df8c', 'subtopic'::public.curated_course_node_type, 'Integrating survey and ethnographic data', 'Students learn to connect patterns with meanings.', 2),
