  ('7517d1de-abac-4825-beeb-89fd8792cea2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'fa322727-6aab-4e6e-b5cb-594e1a956ede', 'concept'::public.curated_course_node_type, 'Using ethnography to design measures', null, 1),
  ('90b82d48-2e2c-4115-8066-c10c4984b41f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'fa322727-6aab-4e6e-b5cb-594e1a956ede', 'concept'::public.curated_course_node_type, 'Joint displays and mixed-method inference', null, 2),
  ('3b4980d8-be51-4d74-b4b3-c4870ce7038c', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Archival, Documentary, and Historical Methods', 'Anthropological fields include archives, bureaucratic records, media, and documents. This topic teaches students to treat texts and records as situated social artifacts.', 10),
  ('14c4f718-0471-45ab-b527-c1cd6db0aabb', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3b4980d8-be51-4d74-b4b3-c4870ce7038c', 'subtopic'::public.curated_course_node_type, 'Finding and evaluating archives', 'Students learn how archival collections are produced, organized, and limited.', 0),
  ('e249dada-3b19-4716-a4e2-8a33fc5e44b4', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '14c4f718-0471-45ab-b527-c1cd6db0aabb', 'concept'::public.curated_course_node_type, 'Finding aids, catalogs, special collections, and digital archives', null, 0),
  ('599dc587-3d5a-4912-8dd9-7f7936b3d5bc', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '14c4f718-0471-45ab-b527-c1cd6db0aabb', 'concept'::public.curated_course_node_type, 'Provenance, silences, gaps, and classification systems', null, 1),
  ('f848cc0e-36cd-4606-8bb7-e65fb671438f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '14c4f718-0471-45ab-b527-c1cd6db0aabb', 'concept'::public.curated_course_node_type, 'Permissions, citation, and reproduction rights', null, 2),
  ('ced877be-bd00-4682-ab86-4586f17e6d7c', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3b4980d8-be51-4d74-b4b3-c4870ce7038c', 'subtopic'::public.curated_course_node_type, 'Document analysis', 'The point is to read documents for content, genre, authorship, circulation, and power.', 1),
  ('bc820a37-eae3-43af-9a96-64f29ec167a7', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'ced877be-bd00-4682-ab86-4586f17e6d7c', 'concept'::public.curated_course_node_type, 'Policy documents, case files, newspapers, reports, social media, and ephemera', null, 0),
  ('1da901fa-c562-4665-89f0-944b7725ad58', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'ced877be-bd00-4682-ab86-4586f17e6d7c', 'concept'::public.curated_course_node_type, 'Discourse, framing, and institutional voice', null, 1),
  ('93e07d0b-70c4-4c3a-8f81-aea6b2c1b26e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'ced877be-bd00-4682-ab86-4586f17e6d7c', 'concept'::public.curated_course_node_type, 'Comparing records with oral and observational data', null, 2),
  ('5c13c20a-8987-44ff-85d1-889093aaad3e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3b4980d8-be51-4d74-b4b3-c4870ce7038c', 'subtopic'::public.curated_course_node_type, 'Historical anthropology', 'Students connect ethnographic questions to temporal depth.', 2),
  ('0485ce30-868d-4d29-8a9d-2042894a90da', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '5c13c20a-8987-44ff-85d1-889093aaad3e', 'concept'::public.curated_course_node_type, 'Genealogies, timelines, memory, and event reconstruction', null, 0),
  ('e055c3d1-3230-4f29-855b-efdc70eff660', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '5c13c20a-8987-44ff-85d1-889093aaad3e', 'concept'::public.curated_course_node_type, 'Colonial records and counter-archives', null, 1),
  ('2025286a-6c25-41bf-8185-b4de811091c2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '5c13c20a-8987-44ff-85d1-889093aaad3e', 'concept'::public.curated_course_node_type, 'Present-day effects of historical processes', null, 2),
  ('90c5e38b-d4ec-4497-82fc-fee10008ac43', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Material Culture, Visual, Spatial, and Digital Methods', 'Anthropological evidence is not only spoken or written. This topic expands methods to objects, images, places, platforms, and digital traces.', 11),
  ('a5230149-da5f-4796-bf2e-990ed1e5554b', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '90c5e38b-d4ec-4497-82fc-fee10008ac43', 'subtopic'::public.curated_course_node_type, 'Material culture methods', 'Students learn to analyze objects as social evidence.', 0),
  ('e053c891-31ba-40bc-a2ba-a74ed797a937', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'a5230149-da5f-4796-bf2e-990ed1e5554b', 'concept'::public.curated_course_node_type, 'Object biographies, use, exchange, repair, display, and disposal', null, 0),
  ('323b4a7c-0b43-4606-b27c-976a2bf05538', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'a5230149-da5f-4796-bf2e-990ed1e5554b', 'concept'::public.curated_course_node_type, 'Museums, collections, and repatriation issues', null, 1),
  ('61a1d83d-4d7d-46ca-9f72-ec1274f9996f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'a5230149-da5f-4796-bf2e-990ed1e5554b', 'concept'::public.curated_course_node_type, 'Materiality, embodiment, and everyday life', null, 2),
  ('6ac75f4c-f827-4616-aa6d-089dfb1312f7', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '90c5e38b-d4ec-4497-82fc-fee10008ac43', 'subtopic'::public.curated_course_node_type, 'Visual and spatial methods', 'The gist is to interpret images and places systematically.', 1),
  ('d3eac812-9547-4eaf-9688-cfafe4051595', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6ac75f4c-f827-4616-aa6d-089dfb1312f7', 'concept'::public.curated_course_node_type, 'Photography, film, sketching, mapping, and spatial walkthroughs', null, 0),
  ('63c413ec-645d-415a-830a-93d86b2497c0', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6ac75f4c-f827-4616-aa6d-089dfb1312f7', 'concept'::public.curated_course_node_type, 'Participatory photography and visual consent', null, 1),
  ('e7ef5adf-fecc-4659-b7c6-c4c918d8e639', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6ac75f4c-f827-4616-aa6d-089dfb1312f7', 'concept'::public.curated_course_node_type, 'GIS concepts, mental maps, and built-environment observation', null, 2),
  ('c6acf456-a418-446b-b5fa-ed4d647b1250', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '90c5e38b-d4ec-4497-82fc-fee10008ac43', 'subtopic'::public.curated_course_node_type, 'Digital ethnography', 'Students learn how online spaces require adapted fieldwork practices.', 2),
  ('794af549-ab46-4d02-b7e6-7843876d7452', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'c6acf456-a418-446b-b5fa-ed4d647b1250', 'concept'::public.curated_course_node_type, 'Platforms, communities, algorithms, and digital publics', null, 0),
  ('a8a215cf-21f8-43ea-9018-268d7d2fa2d0', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'c6acf456-a418-446b-b5fa-ed4d647b1250', 'concept'::public.curated_course_node_type, 'Screenshots, posts, metadata, and terms of service', null, 1),
  ('e6d9ed2c-61e5-4154-8f0e-ca93b3eb7b93', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'c6acf456-a418-446b-b5fa-ed4d647b1250', 'concept'::public.curated_course_node_type, 'Anonymity, traceability, and ethical quoting online', null, 2),
  ('0d853479-a59c-4422-954c-6ca330e81ce2', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Comparative, Multi-Sited, and Team Research', 'Many anthropological questions cross locations, institutions, and scales. This topic helps students design comparative and collaborative projects without losing ethnographic depth.', 12),
  ('9c824b36-5f86-4e0e-8f94-9e76b85a6a7e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '0d853479-a59c-4422-954c-6ca330e81ce2', 'subtopic'::public.curated_course_node_type, 'Comparative logic', 'Students learn how comparison can clarify variation and avoid overgeneralization.', 0),
  ('0d9adb46-d502-428f-8827-62b1936d4f11', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '9c824b36-5f86-4e0e-8f94-9e76b85a6a7e', 'concept'::public.curated_course_node_type, 'Most-similar and most-different cases', null, 0),
  ('d900a12a-6752-48fe-8bc8-ca39fdc68be8', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '9c824b36-5f86-4e0e-8f94-9e76b85a6a7e', 'concept'::public.curated_course_node_type, 'Within-case and cross-case comparison', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('da1fc79a-511a-4a0b-8cc7-0cded5b1a945', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '9c824b36-5f86-4e0e-8f94-9e76b85a6a7e', 'concept'::public.curated_course_node_type, 'Avoiding forced equivalence', null, 2),
  ('2cb396d3-2111-46b4-bc47-29b45ccd9788', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '0d853479-a59c-4422-954c-6ca330e81ce2', 'subtopic'::public.curated_course_node_type, 'Multi-sited ethnography', 'The point is to follow people, objects, ideas, media, money, and policies across settings.', 1),
  ('31699794-b357-4008-afc2-6efbf9de0a9c', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2cb396d3-2111-46b4-bc47-29b45ccd9788', 'concept'::public.curated_course_node_type, 'Follow the thing, metaphor, plot, conflict, biography, or policy', null, 0),
  ('ac392590-c742-461f-97c9-9d802e547eaf', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2cb396d3-2111-46b4-bc47-29b45ccd9788', 'concept'::public.curated_course_node_type, 'Scale, mobility, and transnational fields', null, 1),
  ('5b0dcb78-0817-4967-83e7-b5ae441e3e5e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '2cb396d3-2111-46b4-bc47-29b45ccd9788', 'concept'::public.curated_course_node_type, 'Managing uneven access across sites', null, 2),
  ('adc80599-636f-4c6b-be45-8f954292e70b', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '0d853479-a59c-4422-954c-6ca330e81ce2', 'subtopic'::public.curated_course_node_type, 'Team research', 'Students learn practices for collaborative rigor.', 2),
  ('bcb05fb6-3694-4cce-b80f-7f9dc87a024e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'adc80599-636f-4c6b-be45-8f954292e70b', 'concept'::public.curated_course_node_type, 'Shared protocols and codebooks', null, 0),
  ('a575b8c0-e141-4a9a-8470-9ce1630f2572', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'adc80599-636f-4c6b-be45-8f954292e70b', 'concept'::public.curated_course_node_type, 'Intercoder discussion and calibration', null, 1),
  ('455eebec-acbb-448f-ae21-6db7006d3316', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', 'adc80599-636f-4c6b-be45-8f954292e70b', 'concept'::public.curated_course_node_type, 'Authorship, labor, and project management', null, 2),
  ('1128f1e0-802f-4e91-aaaa-692d1937004e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Qualitative Coding and Analysis', 'Analysis begins during fieldwork and deepens after data collection. This topic teaches students to code, memo, compare, and build arguments from qualitative material.', 13),
  ('3ac433a6-1362-4d9f-9d9e-46b414968010', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '1128f1e0-802f-4e91-aaaa-692d1937004e', 'subtopic'::public.curated_course_node_type, 'Coding strategies', 'Students learn coding as disciplined interpretation, not mechanical labeling.', 0),
  ('8fa2b9ea-896e-47a7-8c92-2f8a9597b89f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3ac433a6-1362-4d9f-9d9e-46b414968010', 'concept'::public.curated_course_node_type, 'Open, descriptive, in vivo, process, values, and focused coding', null, 0),
  ('500d6616-58b5-4252-8053-9855be807777', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3ac433a6-1362-4d9f-9d9e-46b414968010', 'concept'::public.curated_course_node_type, 'Codebooks, definitions, inclusion criteria, and examples', null, 1),
  ('dcfec99c-f5b8-407f-b616-d9d7bf35f6fb', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '3ac433a6-1362-4d9f-9d9e-46b414968010', 'concept'::public.curated_course_node_type, 'Iterative recoding and code consolidation', null, 2),
  ('6f26a518-5fb5-4d3a-8b87-03947b8e46c9', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '1128f1e0-802f-4e91-aaaa-692d1937004e', 'subtopic'::public.curated_course_node_type, 'Thematic and interpretive analysis', 'The point is to move from codes to patterns, relationships, and claims.', 1),
  ('d20ec608-1475-4755-856b-9a8fcc96b278', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6f26a518-5fb5-4d3a-8b87-03947b8e46c9', 'concept'::public.curated_course_node_type, 'Themes, categories, typologies, and narratives', null, 0),
  ('b5f6b6da-7298-4139-9df7-c4417f913c1f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6f26a518-5fb5-4d3a-8b87-03947b8e46c9', 'concept'::public.curated_course_node_type, 'Negative cases and rival explanations', null, 1),
  ('f73cbca6-6fa7-40e1-be22-ee06919d6b96', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '6f26a518-5fb5-4d3a-8b87-03947b8e46c9', 'concept'::public.curated_course_node_type, 'Thick description and analytic abstraction', null, 2),
  ('06b6f7a2-a6a7-46fb-872e-60600ff8110e', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '1128f1e0-802f-4e91-aaaa-692d1937004e', 'subtopic'::public.curated_course_node_type, 'Software-supported analysis', 'Students learn what tools can and cannot do.', 2),
  ('00bc8d67-5cb4-4219-bf68-5276654ea709', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '06b6f7a2-a6a7-46fb-872e-60600ff8110e', 'concept'::public.curated_course_node_type, 'NVivo, MAXQDA, Dedoose, Atlas.ti, spreadsheets, and manual coding', null, 0),
  ('fe71fe27-8415-4ae7-b4cb-8db24fe90b74', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '06b6f7a2-a6a7-46fb-872e-60600ff8110e', 'concept'::public.curated_course_node_type, 'Queries, matrices, memos, and audit trails', null, 1),
  ('ea3922a0-4654-4635-bbd2-1acb0fd89924', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '06b6f7a2-a6a7-46fb-872e-60600ff8110e', 'concept'::public.curated_course_node_type, 'Avoiding software-driven superficial analysis', null, 2),
  ('7b5cdef3-bde9-4fbd-b665-0bfb27afd9df', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', null, 'topic'::public.curated_course_node_type, 'Quantitative Data, Statistics, and Visualization for Anthropologists', 'Anthropological researchers need enough quantitative fluency to interpret surveys, demographics, networks, and mixed-method evidence. This topic emphasizes practical, transparent analysis.', 14),
  ('8bf3b0b4-bedf-4786-93d5-ff3a0b32255f', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7b5cdef3-bde9-4fbd-b665-0bfb27afd9df', 'subtopic'::public.curated_course_node_type, 'Descriptive statistics', 'Students learn to summarize data without overstating what it proves.', 0),
  ('08345334-6450-4223-bbae-d49ec5dd10be', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '8bf3b0b4-bedf-4786-93d5-ff3a0b32255f', 'concept'::public.curated_course_node_type, 'Counts, percentages, means, medians, distributions, and cross-tabs', null, 0),
  ('f135d5a6-671f-4496-98ea-51cd0d0a5943', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '8bf3b0b4-bedf-4786-93d5-ff3a0b32255f', 'concept'::public.curated_course_node_type, 'Missing data and outliers', null, 1),
  ('461cd72a-a04a-4ecc-94f5-66fe4fbb7aee', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '8bf3b0b4-bedf-4786-93d5-ff3a0b32255f', 'concept'::public.curated_course_node_type, 'Small-sample caution', null, 2),
  ('75d1bb16-e65d-49f5-b645-ecf6b794bc45', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7b5cdef3-bde9-4fbd-b665-0bfb27afd9df', 'subtopic'::public.curated_course_node_type, 'Applied analysis', 'The goal is basic competence with common tools and outputs.', 1),
  ('152c380c-3e02-4fce-8b1d-aecbf94e5870', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '75d1bb16-e65d-49f5-b645-ecf6b794bc45', 'concept'::public.curated_course_node_type, 'Spreadsheets, R, SPSS, or Python at an introductory level', null, 0),
  ('dd8bec29-525a-4e6e-8d6a-48e0b8a1b7d8', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '75d1bb16-e65d-49f5-b645-ecf6b794bc45', 'concept'::public.curated_course_node_type, 'Comparisons, associations, simple regression concepts, and confidence intervals', null, 1),
  ('20f09342-5b43-40c8-a818-3fb727daf8b8', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '75d1bb16-e65d-49f5-b645-ecf6b794bc45', 'concept'::public.curated_course_node_type, 'Choosing analysis appropriate to measurement and sampling', null, 2),
  ('b5932143-f91b-448f-8ca3-b5ab2b1b6fb6', 'd8e9f0a1-2b3c-4e18-9f78-8a9b0c1d2e88', '7b5cdef3-bde9-4fbd-b665-0bfb27afd9df', 'subtopic'::public.curated_course_node_type, 'Visualization and communication', 'Students learn to make visuals that clarify rather than impress.', 2),
